import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import { Card, List, Comment, Tooltip, Row, Result, notification, Spin } from 'antd'
import { AvaStyle, AvaChatbotWrapper } from './index.style'
import AvaActions from '../../redux/ava/action'
import errorAction from '../../../redux/error/actions'
import loadingAction from '../../../redux/loading/actions'
import { BASE_IMG_URL_S3 } from '../../../helpers/constant'

const { getAvaChat } = AvaActions
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = errorAction

class Ava extends Component {
  constructor(props) {
    super(props)
    this.state = {
      completeChatData: [],
      sessionID: ""
    }
  }

  componentDidMount() {
    const sessionID = new URLSearchParams(this.props.location.search).get("session_id")
    this.setState({ sessionID })

    if (sessionID) {
      this.props.getAvaChat({
        query: {
          session_id: sessionID
        }
      })
    }

    this.props.resetLoadingRedux(['GET_AVA_CHAT'])
    this.props.resetErrorRedux(['GET_AVA_CHAT'])
  }

  UNSAFE_componentWillReceiveProps(nextProps) {
    const {
      avaChatLoading, avaChatError, avaChatMessage, avaChat
    } = nextProps

    if (avaChatLoading === false) {
      if (avaChatError === false) {
        this.messageFormatting(avaChat?.chat)
      } else {
        notification["error"]({ message: 'Error', description: avaChatMessage })
      }
      this.props.resetLoadingRedux(['GET_AVA_CHAT'])
      this.props.resetErrorRedux(['GET_AVA_CHAT'])
    }
  }

  messageContentAva = (replyText = [], quickReplies = [], cards = []) => {
    return <AvaStyle>
      {
        replyText && <p>
          {
            replyText.map(reply => <p>{reply}</p>)
          }
        </p>
      }
      {
        quickReplies && <Row type='flex'>
          {
            quickReplies.map(quickReply => <div className='quickReply'>{quickReply}</div>)
          }
        </Row>
      }
      {
        cards && <AvaChatbotWrapper>
          {
            cards.map((card, index) => <Card key={index}><div className='card' dangerouslySetInnerHTML={{ __html: card }} /></Card>)
          }
        </AvaChatbotWrapper>
      }
    </AvaStyle>
  }

  messageFormatting = (messageData = []) => {
    const allData = messageData.map(({ message_type: messageType, message = {}, time }) => {
      const { reply_texts: replyText, quick_replies: quickReplies, cards } = message
      return {
        author: (<b>{messageType}</b>),
        content: messageType === "AVA" ? (this.messageContentAva(replyText, quickReplies, cards)
        ) : message.text,
        avatar: (messageType === "VISITOR" ? `${BASE_IMG_URL_S3}/gosure/user_default_icon%202.png` : `${BASE_IMG_URL_S3}/ava/bot-icon.svg`),
        datetime: (
          <Tooltip title={moment(time).add(7, 'hours').format('YYYY-MM-DD HH:mm:ss A')}>
            <span>{moment(time).add(7, 'hours').format('YYYY-MM-DD HH:mm:ss A')}</span>
          </Tooltip>
        )
      }
    })
    this.setState({ completeChatData: allData })
  }

  render() {
    const { avaChatLoading } = this.props
    const { completeChatData = [], sessionID } = this.state

    return (
      <Spin spinning={!!avaChatLoading}>
        <AvaStyle>
          <Card>
            <h3 className='header'>Session ID: {sessionID}</h3>
            {
              sessionID
                ?
                <List
                  className="comment-list"
                  header={`${completeChatData.length} messages`}
                  itemLayout="horizontal"
                  dataSource={completeChatData}
                  renderItem={item => (
                    <li>
                      <Comment
                        actions={item.actions}
                        author={item.author}
                        avatar={item.avatar}
                        content={item.content}
                        datetime={item.datetime}
                      />
                    </li>
                  )}
                />
                :
                <Result
                  status="500"
                  title="404"
                  subTitle="No Session ID found for getting chats"
                />
            }
          </Card>
        </AvaStyle>
      </Spin>
    )
  }
}

export default connect(
  state => ({
    avaChatLoading: state.Loading.GET_AVA_CHAT,
    avaChatError: state.Error.GET_AVA_CHAT,
    avaChat: state.Ava.avaChat
  }),
  {
    getAvaChat,
    resetLoadingRedux,
    resetErrorRedux
  }
)(Ava)
